#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Cloudflare R2 for game images (#139). The values go to Vercel, the
# Production environment and the staging branch (ADR 0007). They never go to
# the repo or to the local .env. --dry-run walks every stage without opening
# a browser, calling Vercel or needing Cloudflare access.
# ──────────────────────────────────────────────────────────────────────────

# Set by --dry-run: pages are printed, not opened; values are placeholders;
# Vercel is never called.
DRY_RUN=0
ROOT=""
R2_JURISDICTION=""  # eu, or empty for the location hint (default endpoint)
VERCEL_SET=()       # "NAME for ENV" entries written this run
VERCEL_ERR=""       # stderr of the last vercel env add, never the value

# page URL opens a page, or only prints it in a dry run.
page() {
  if (( DRY_RUN )); then
    printf '  %s○ dry run, not opening%s %s\n' "$DIM" "$RESET" "$1"
  else
    open_url "$1"
  fi
}

# need KIND KEY "Prompt" REGEX "hint": asks until the value matches REGEX, then
# sets $KEY. KIND is visible or secret (hidden input). Three tries, then stop.
# A dry run takes a placeholder so the walk-through needs no input.
need() {
  local kind="$1" key="$2" prompt="$3" regex="$4" hint="$5" tries=0 value
  while :; do
    if [[ "$kind" == secret ]]; then ask_secret "$key" "$prompt" || true
    else ask "$key" "$prompt" || true; fi
    value="${!key:-}"
    # Trim the ends only (a pasted newline or space); inner spaces stay and fail REGEX.
    value="${value#"${value%%[![:space:]]*}"}"
    value="${value%"${value##*[![:space:]]}"}"
    printf -v "$key" '%s' "$value"
    if (( DRY_RUN )); then
      [[ -n "$value" ]] || printf -v "$key" '%s' '<dry-run>'
      note "dry run: $key is a placeholder"
      return 0
    fi
    if [[ "$value" =~ $regex ]]; then
      printf '  %s✓ captured%s %s\n' "$GREEN" "$RESET" "$key"
      return 0
    fi
    tries=$((tries + 1))
    if (( tries >= 3 )); then
      warn "$key is still empty or malformed. Stopping; re-run the wizard."
      exit 1
    fi
    warn "that doesn't look right ($hint). Try again."
  done
}

# ask_eu asks which jurisdiction the buckets got, and sets R2_JURISDICTION.
ask_eu() {
  if (( DRY_RUN )); then
    R2_JURISDICTION=eu
    note "dry run: assuming the European Union (EU) jurisdiction"
  elif confirm "Did you choose the European Union (EU) jurisdiction for both buckets?"; then
    R2_JURISDICTION=eu
  else
    R2_JURISDICTION=""
  fi
  if [[ -n "$R2_JURISDICTION" ]]; then
    printf '  %s✓%s R2_JURISDICTION=eu (endpoint <account>.eu.r2.cloudflarestorage.com)\n' "$GREEN" "$RESET"
  else
    printf '  %s✓%s no jurisdiction set: location hint, default endpoint\n' "$GREEN" "$RESET"
  fi
}

# yes_or_stop "question" is a gate: a no stops the wizard, so later stages never
# run on buckets or tokens that don't exist yet.
yes_or_stop() {
  if (( DRY_RUN )); then
    note "dry run: assuming yes: $1"
    return 0
  fi
  confirm "$1" || {
    warn "Finish that step in Cloudflare, then re-run the wizard."
    exit 1
  }
}

# _vercel_add NAME VALUE ENVIRONMENT [BRANCH] adds one variable. The value goes
# in on stdin, so it never shows up in argv, output or shell history.
_vercel_add() {
  VERCEL_ERR=$(printf '%s' "$2" | vercel env add "$1" "$3" ${4:+"$4"} 2>&1 >/dev/null)
}

# vercel_set NAME VALUE ENVIRONMENT [BRANCH] writes NAME to Vercel. An existing
# variable is replaced after you confirm. Only the name and target are printed.
vercel_set() {
  local name="$1" value="$2" target="$3" branch="${4:-}" label
  label="$name for $target${branch:+ (branch $branch)}"
  if (( DRY_RUN )); then
    printf '  %s○ dry run, would run%s vercel env add %s %s%s (value on stdin)\n' \
      "$DIM" "$RESET" "$name" "$target" "${branch:+ $branch}"
    VERCEL_SET+=("$label")
    return 0
  fi
  if _vercel_add "$name" "$value" "$target" "$branch"; then
    printf '  %s✓ set%s %s\n' "$GREEN" "$RESET" "$label"
    VERCEL_SET+=("$label")
    return 0
  fi
  if [[ "$VERCEL_ERR" == *"already exists"* ]] && confirm "$label already exists. Replace it?"; then
    if vercel env rm "$name" "$target" ${branch:+"$branch"} --yes >/dev/null 2>&1 \
      && _vercel_add "$name" "$value" "$target" "$branch"; then
      printf '  %s✓ replaced%s %s\n' "$GREEN" "$RESET" "$label"
      VERCEL_SET+=("$label")
      return 0
    fi
  fi
  SKIPPED+=("Vercel $name for $target${branch:+ (branch $branch)}: set it in the dashboard")
  warn "couldn't set $label. Vercel said: ${VERCEL_ERR:-nothing}"
}

# vercel_by_hand is the fallback without the Vercel CLI: the same variables,
# typed into the dashboard. The wizard captures no secrets in this mode.
vercel_by_hand() {
  warn "Without the Vercel CLI this wizard can't set the variables. Do it by hand:"
  step "Open https://vercel.com/dashboard, then the COMPIES project, then Settings → Environment Variables."
  step "Add R2_ACCOUNT_ID, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY and R2_BUCKET for the Production environment."
  step "Set R2_BUCKET to compies-production there, and R2_JURISDICTION to eu if you chose the EU jurisdiction."
  step "Add the same variables for the Preview environment, limited to the git branch staging."
  step "Set R2_BUCKET to compies-staging there. Use the values from the Cloudflare pages in this wizard."
  note "Then redeploy staging and production so the new variables apply."
  exit 0
}

run_wizard() {

for arg in "$@"; do
  case "$arg" in
    --dry-run) DRY_RUN=1 ;;
    -h|--help)
      printf 'Usage: scripts/wizards/r2-setup.sh [--dry-run]\n'
      printf '  --dry-run  walk every stage without opening browsers or calling Vercel\n'
      exit 0 ;;
    *) printf 'Unknown option: %s\n' "$arg" >&2; exit 2 ;;
  esac
done

# Vercel links and ENV_FILE are relative to the repo root, wherever you start from.
ROOT=$(cd "$(dirname "$0")/../.." && pwd)
cd "$ROOT"

TOTAL_STAGES=8

banner "COMPIES: Cloudflare R2 for game images (#139)"

# ── Stage 1: Vercel ───────────────────────────────────────────────────────
stage "Vercel: CLI, sign-in and project link"
say "The variables go into Vercel, so this needs the Vercel CLI, a sign-in and the linked COMPIES project."
if (( DRY_RUN )); then
  note "dry run: would check the Vercel CLI, sign-in and the .vercel/ link"
else
  if ! command -v vercel >/dev/null 2>&1; then
    warn "The Vercel CLI is not installed."
    if confirm "Install it now with npm (npm install -g vercel)?"; then
      npm install -g vercel || warn "npm could not install the Vercel CLI"
    fi
  fi
  command -v vercel >/dev/null 2>&1 || vercel_by_hand
  if ! vercel whoami >/dev/null 2>&1; then
    say "Sign in to Vercel. The CLI opens a browser or prints a link to open."
    vercel login || true
  fi
  vercel whoami >/dev/null 2>&1 || { warn "Still not signed in to Vercel. Run vercel login, then re-run the wizard."; exit 1; }
  printf '  %s✓%s signed in to Vercel as %s\n' "$GREEN" "$RESET" "$(vercel whoami 2>/dev/null | tail -n1)"
  if [[ ! -f "$ROOT/.vercel/project.json" ]]; then
    say "Link this checkout to the existing COMPIES project. Pick the team that owns it."
    vercel link || { warn "vercel link did not finish. Re-run the wizard after linking."; exit 1; }
  fi
  printf '  %s✓%s the checkout is linked to the Vercel project\n' "$GREEN" "$RESET"
fi
pause "Press Enter to continue."

# ── Stage 2: Cloudflare account ───────────────────────────────────────────
stage "Cloudflare: create or sign in to your account"
say "Cloudflare hosts the image buckets (R2). The Free plan is enough for COMPIES."
page "https://dash.cloudflare.com/sign-up"
step "Sign up with your email and a password, then confirm the email. If you have an account, sign in."
step "Choose the Free plan when Cloudflare asks which plan to use."
pause "Press Enter once you see the Cloudflare dashboard."

# ── Stage 3: enable R2, Account ID ────────────────────────────────────────
stage "Cloudflare: enable R2 and copy the Account ID"
page "https://dash.cloudflare.com/"
step "In the left sidebar, click R2 Object Storage. If you can't find it, type R2 into the search box at the top."
note "If R2 asks for a payment method, add one. The free tier (10 GB storage, 1 million Class A and 10 million Class B operations a month) covers COMPIES as long as you stay within it."
pause "Press Enter once the R2 overview page is open."
step "On the R2 overview page, find the Account ID on the right side, and copy it."
need visible R2_ACCOUNT_ID "Paste the Account ID:" '^[[:graph:]]+$' "one word without spaces"

# ── Stage 4: buckets ──────────────────────────────────────────────────────
stage "Cloudflare: create the two buckets"
say "One bucket per environment, both private. Use these names exactly:"
step "compies-staging (the staging branch)"
step "compies-production (production)"
step "On the R2 overview page, click the button that creates a bucket, usually 'Create bucket'."
step "Type the bucket name, then choose the location (next line). Repeat for the second bucket."
step "Location: if the form offers 'Specify jurisdiction', choose European Union (EU). Otherwise pick the location hint Western Europe (WEUR). Use the same choice for both buckets."
step "Leave public access off. The app serves images through its own route, not a public bucket."
pause "Press Enter once both buckets are listed on the R2 overview page."
ask_eu
yes_or_stop "Are both buckets listed with exactly these names, and public access off?"

# ── Stage 5: API token ────────────────────────────────────────────────────
stage "Cloudflare: create the R2 API token"
step "On the R2 overview page, click 'Manage R2 API Tokens' (usually top right), then 'Create API token'."
step "Name: compies-images (any name works)."
step "Permissions: Object Read & Write."
step "Bucket scope: 'Apply to specific buckets only', then select compies-staging and compies-production."
step "Click the button that creates the token."
warn "Cloudflare shows the Access Key ID and the Secret Access Key once. Keep the page open until both are copied."
note "Use the Access Key ID and the Secret Access Key, not the token value Cloudflare also shows."
need secret R2_ACCESS_KEY_ID "Paste the Access Key ID (input stays hidden):" '^[[:graph:]]+$' "one word without spaces"
need secret R2_SECRET_ACCESS_KEY "Paste the Secret Access Key (input stays hidden):" '^[[:graph:]]+$' "one word without spaces"

# ── Stage 6: Vercel production ────────────────────────────────────────────
stage "Vercel: variables for production (branch main)"
say "Writes the Production environment. Production uploads go to compies-production."
vercel_set R2_ACCOUNT_ID "$R2_ACCOUNT_ID" production
vercel_set R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID" production
vercel_set R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY" production
vercel_set R2_BUCKET compies-production production
if [[ -n "$R2_JURISDICTION" ]]; then
  vercel_set R2_JURISDICTION "$R2_JURISDICTION" production
fi
pause "Press Enter to continue."

# ── Stage 7: Vercel staging branch ────────────────────────────────────────
stage "Vercel: variables for the staging branch (Preview)"
say "Writes the Preview environment, limited to the git branch staging (ADR 0007). Staging uploads go to compies-staging."
vercel_set R2_ACCOUNT_ID "$R2_ACCOUNT_ID" preview staging
vercel_set R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID" preview staging
vercel_set R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY" preview staging
vercel_set R2_BUCKET compies-staging preview staging
if [[ -n "$R2_JURISDICTION" ]]; then
  vercel_set R2_JURISDICTION "$R2_JURISDICTION" preview staging
fi
pause "Press Enter to continue."

# ── Stage 8: check and finish ─────────────────────────────────────────────
stage "Check the result"
if (( DRY_RUN )); then
  note "dry run: would run vercel env ls production and vercel env ls preview staging"
else
  # Names and targets only: Vercel shows stored values as encrypted.
  printf '  %sproduction%s\n' "$BOLD" "$RESET"
  vercel env ls production 2>/dev/null | grep -E 'R2_' || warn "no R2_ variables listed for production"
  printf '  %spreview staging%s\n' "$BOLD" "$RESET"
  vercel env ls preview staging 2>/dev/null | grep -E 'R2_' || warn "no R2_ variables listed for preview staging"
fi
if (( ${#VERCEL_SET[@]} )); then
  verb="set"
  (( DRY_RUN )) && verb="would set"
  printf '\n'
  for entry in "${VERCEL_SET[@]}"; do note "$verb: $entry"; done
fi
say "Local development: leave the R2 variables empty in .env unless you test image upload against a real bucket."
say "Vercel applies new variables to new deployments: redeploy staging and production after this run."
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
